SELECT setval('public.accounts_id_seq',
  greatest((SELECT max(id) FROM public.clients), (SELECT max(id) FROM public.partner)), true);
SELECT setval('public.devices_id_seq', 100, true);
SELECT setval('public.client_addresses_id_seq', 100, true);
SELECT setval('public.partner_services_id_seq', 100, true);
SELECT setval('public.support_messages_id_seq', 100, true);
SELECT setval('public.work_items_id_seq', greatest(
  (SELECT max(id) FROM public.repair_orders),
  coalesce((SELECT max(id) FROM public.workflow_records), 0)
), true);
SELECT setval('public.reviews_id_seq', 100, true);

COMMIT;

